//refAssemblies: System.Diagnostics.Process.dll, TCAdmin.Monitor.SDK.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Wine (Linux host) only: installs what the panel needs to run this Windows server - wine, winetricks, Xvfb and
// xdotool - with apt (Debian/Ubuntu) or dnf/yum (Red Hat), and the Windows runtimes listed in Verbs into the service's
// own Wine prefix. Idempotent: anything already present is skipped. Runs before the create/reinstall (host packages,
// so the panel's Wine check passes) and after it (prefix runtimes, once the service user and files exist).
if (!System.OperatingSystem.IsLinux()) return;

// Windows runtimes (winetricks verbs) the server needs inside the prefix. The server runs on Wine's built-in
// Visual C++ runtime, so none are required today; add verbs here when a game update needs one.
var verbs = new string[] { };

var tools = new (string Command, string[] Apt, string[] Rpm)[]
{
    ("wine", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("wineserver", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("winetricks", new[] { "winetricks" }, new[] { "winetricks" }),
    ("cabextract", new[] { "cabextract" }, new[] { "cabextract" }),
    ("Xvfb", new[] { "xvfb" }, new[] { "xorg-x11-server-Xvfb", "xorg-x11-server-Xvfb.x86_64" }),
    ("xdotool", new[] { "xdotool" }, new[] { "xdotool" }),
};
var apt = Shell("command -v apt-get", out _);
var installer = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
var updated = false;
foreach (var tool in tools)
{
    if (Shell("command -v " + tool.Command, out _)) continue;
    var names = apt ? tool.Apt : tool.Rpm;
    ScriptConsole.WriteLine((object)(tool.Command + " is missing on this host; installing " + string.Join(" or ", names) + "."));
    var installed = names.Any(p => Shell(installer + p, out _));
    if (!installed && apt && !updated)
    {
        updated = Shell("DEBIAN_FRONTEND=noninteractive apt-get update", out _);
        installed = names.Any(p => Shell(installer + p, out _));
    }
    if (!installed || !Shell("command -v " + tool.Command, out _))
        throw new Exception(tool.Command + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
}
Shell("wine --version", out var wineVersion);
ScriptConsole.WriteLine((object)("Wine on this host: " + wineVersion.Trim()));

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/');
// Before the create/reinstall the service files and its run-as configuration do not exist yet.
string user = null;
if (File.Exists(Path.Combine(root, "LF", "Binaries", "Win64", "LFServer-Win64-Shipping.exe")))
{
    try { user = ServiceManagerService.GetServiceCredential(ThisService.ServiceId)?.UserName; }
    catch (FileNotFoundException) { }
}
if (string.IsNullOrEmpty(user) || !Shell("id -u '" + user + "'", out _))
{
    ScriptConsole.WriteLine((object)"The service is not created yet; the Wine prefix is prepared after the files are installed.");
    return;
}
var prefix = Path.Combine(root, ".wine");
// Every Wine call as the service user with the environment the panel starts the server with (root would leave
// root-owned files in the prefix).
var wineEnv = "runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' HOME='" + root
              + "' WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' ";

// The first start creates the Wine prefix (about a minute), longer than the panel waits for the start that follows
// the create, so that start failed. Create the prefix here; the panel skips it when its marker file is present.
var marker = Path.Combine(prefix, ".tcadmin-initialized");
if (!File.Exists(marker))
{
    ScriptConsole.WriteLine((object)"Creating the Wine prefix (about a minute).");
    if (!Shell(wineEnv + "wineboot -u", out var bootOutput))
        throw new Exception("wineboot failed: " + string.Join("\n", bootOutput.Split('\n').TakeLast(15)));
    Shell(wineEnv + "wineserver -w", out _);
    Shell("runuser -u '" + user + "' -- sh -c \"date -u +%Y-%m-%dT%H:%M:%SZ > '" + marker + "'\"", out _);
    ScriptConsole.WriteLine((object)"The Wine prefix is ready.");
}

if (verbs.Length == 0) return;
// winetricks records every verb it installed in the prefix.
var log = Path.Combine(prefix, "winetricks.log");
var done = File.Exists(log) ? File.ReadAllLines(log).Select(l => l.Trim()).ToHashSet() : new HashSet<string>();
var todo = verbs.Where(v => !done.Contains(v)).ToList();
if (todo.Count == 0)
{
    ScriptConsole.WriteLine((object)("Windows runtimes already installed: " + string.Join(", ", verbs) + "."));
    return;
}
ScriptConsole.WriteLine((object)("Installing " + string.Join(", ", todo) + " into the Wine prefix (a few minutes)."));
var command = wineEnv + "winetricks -q " + string.Join(" ", todo);
if (!Shell(command, out var output))
    throw new Exception("winetricks failed: " + string.Join("\n", output.Split('\n').TakeLast(15)));
Shell(wineEnv + "wineserver -w", out _);
ScriptConsole.WriteLine((object)"Windows runtimes installed.");

bool Shell(string cmd, out string text)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", cmd }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        text = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

//refAssemblies: System.Net.Http.dll, System.IO.Compression.dll, System.IO.Compression.ZipFile.dll, System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop: the server shuts down cleanly on ONE Ctrl+C.
// Windows: a Ctrl+C sent through its console does not reach it (it ignores console Ctrl+C events), so windows-kill
// delivers the event straight to the server process. Linux (Wine): a native SIGINT to the server's Wine process
// becomes the console Ctrl+C. Only the server process of THIS service is signalled.
const string binary = "LFServer-Win64-Shipping";
const int maxWaitSeconds = 120;

var rootPath = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
var root = rootPath + Path.DirectorySeparatorChar;
var rootSlash = rootPath.Replace('\\', '/') + "/";

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(binary))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    // Wine shows the executable as Z:\<root>\...\LFServer-Win64-Shipping.exe in the command line.
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var args = File.ReadAllText(Path.Combine(dir, "cmdline")).Replace('\0', ' ').Replace('\\', '/');
            if (args.Contains(binary + ".exe", StringComparison.OrdinalIgnoreCase) && args.Contains(rootSlash, StringComparison.Ordinal)
                && !args.Contains("start.exe", StringComparison.OrdinalIgnoreCase))
                pids.Add(pid);
        }
        catch { } // gone meanwhile
    }
    pids.Sort();
    return pids;
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

if (System.OperatingSystem.IsWindows())
{
    // windows-kill is kept in the hidden .tca folder of the service and downloaded once.
    var toolDir = Path.Combine(rootPath, ".tca");
    var killExe = Path.Combine(toolDir, "windows-kill.exe");
    if (!File.Exists(killExe))
    {
        const string url = "https://github.com/ElyDotDev/windows-kill/releases/download/1.1.4/windows-kill_1.1.4_release.zip";
        const string entryPath = "windows-kill_x64_1.1.4_lib_release/windows-kill.exe";
        try
        {
            Directory.CreateDirectory(toolDir);
            using (var http = new HttpClient())
            using (var zip = new ZipArchive(new MemoryStream(await http.GetByteArrayAsync(url, ThisCancellationToken))))
            {
                var entry = zip.GetEntry(entryPath);
                if (entry == null) throw new Exception("'" + entryPath + "' is not in the archive.");
                entry.ExtractToFile(killExe, true);
            }
        }
        catch (Exception ex)
        {
            ScriptConsole.WriteLine((object)("Could not download windows-kill (" + ex.Message + "); the panel stops the server without saving."));
            return;
        }
    }
    foreach (var pid in targets)
    {
        // CreateNoWindow gives windows-kill a console of its own, so the event never reaches the monitor.
        var psi = new ProcessStartInfo(killExe, new[] { "-SIGINT", pid.ToString() })
        {
            UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true,
            WorkingDirectory = toolDir
        };
        using (var killer = Process.Start(psi))
        {
            var output = (await killer.StandardOutput.ReadToEndAsync()).Trim();
            await killer.WaitForExitAsync(ThisCancellationToken);
            if (killer.ExitCode != 0) ScriptConsole.WriteLine((object)("windows-kill: " + output));
        }
    }
}
else
{
    // One SIGINT to the main server process (the lowest pid); its worker threads share it.
    targets = targets.Take(1).ToList();
    using (var kill = Process.Start(new ProcessStartInfo("kill", new[] { "-INT", targets[0].ToString() }) { UseShellExecute = false }))
        kill.WaitForExit();
}

ScriptConsole.WriteLine((object)("Asked the server (" + string.Join(", ", targets) + ") to save and exit."));
for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!ServerPids().Any(targets.Contains))
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

//refAssemblies: TCAdmin.Web.Shared.dll, System.Net.NetworkInformation.dll, System.Net.Primitives.dll
using System;
using System.Linq;
using System.Net;
using System.Net.NetworkInformation;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Night of the Dead lists its servers through Epic Online Services sessions: the Steam query port is bound by the
// Steam API but never answers (the server never logs on to Steam), and the server has no RCON. The query runs on the
// monitor of the server that hosts the service, so it checks that the game UDP port is bound on this machine.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
// The game port is the one the server binds itself (-Port); the query port belongs to the Steam API.
int port = ThisService.GamePort;

try
{
    IPAddress.TryParse(address, out var ip);
    var listening = IPGlobalProperties.GetIPGlobalProperties().GetActiveUdpListeners()
        .Any(l => l.Port == port && (ip == null || l.Address.Equals(ip) || l.Address.Equals(IPAddress.Any) || l.Address.Equals(IPAddress.IPv6Any)));
    Globals.ReturnValue = listening
        ? new GameQueryResponse
        {
            Success = true,
            Status = "online",
            Protocol = "custom_script",
            Address = address,
            Hostname = $"{address}:{port}",
            Name = ThisService.Name,
            GameType = "Night of the Dead",
            Map = "",
            NumPlayers = 0,
            MaxPlayers = ThisService.Slots,
            NumSpectators = 0,
            MaxSpectators = 0,
            Retries = 0
        }
        : GameQueryResponse.DefaultOfflineResponse(address, "custom_script", $"Nothing is listening on {address}:{port} (UDP).");
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

using System;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Wine: the Steam client library crashes while the server unloads it at the very end of a stop (after the game has
// shut down), and the engine writes a crash report (about 550 KB) into LF/Saved/Crashes on every stop. Keep the
// newest five reports, delete the rest. This script runs as root: it never follows a symbolic link (a linked
// folder or report is left alone) and touches nothing outside the two crash folders below.
if (!System.OperatingSystem.IsLinux()) return;
const int keep = 5;
var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/');
var removed = 0;
// Each crash leaves a report folder in LF/Saved/Crashes and a small settings folder in LF/Saved/Config/CrashReportClient.
foreach (var folder in new[] { new[] { "LF", "Saved", "Crashes" }, new[] { "LF", "Saved", "Config", "CrashReportClient" } })
    removed += Prune(folder);
if (removed > 0) ScriptConsole.WriteLine((object)("Deleted " + removed + " old crash report folder(s)."));

int Prune(string[] parts)
{
    var path = root;
    foreach (var part in parts)
    {
        path = Path.Combine(path, part);
        var info = new DirectoryInfo(path);
        if (!info.Exists) return 0;
        if (info.LinkTarget != null)
        {
            ScriptConsole.WriteLine((object)(path.Substring(root.Length) + " is a symbolic link; it is left alone."));
            return 0;
        }
    }
    var count = 0;
    var old = new DirectoryInfo(path).GetDirectories("UECC-*")
        .Where(d => d.LinkTarget == null && (d.Attributes & FileAttributes.ReparsePoint) == 0)
        .OrderByDescending(d => d.LastWriteTimeUtc)
        .Skip(keep);
    foreach (var dir in old)
    {
        try { dir.Delete(true); count++; }
        catch (Exception ex) { ScriptConsole.WriteLine((object)("Could not delete " + dir.Name + ": " + ex.Message)); }
    }
    return count;
}
